sql.where:
deleted_yn = 'N'
and evaluation_year = #{criteria.evaluationYear}
and management_no ilike '%' || #{criteria.managementNo} || '%'
and teacher_name ilike '%' || #{criteria.teacherName} || '%'
and management_item_code = #{criteria.managementItemCode}
and occurred_date >= #{criteria.occurredDateFrom}
and occurred_date <= #{criteria.occurredDateTo}
and certification_status = #{criteria.certificationStatus}
